import { Snackbar } from '@refy-design/web';
import { useState } from 'react';
export function Example() {
  const [moved, setMoved] = useState(true);
  return (
    <Snackbar
      action={{ label: moved ? 'Undo' : 'Move again', onClick: () => setMoved(!moved) }}
    >
      {moved ? 'Item moved to Tasks' : 'Move undone'}
    </Snackbar>
  );
}

